-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id": "e9eeae4f-c4ae-451c-8baa-fe8d7668b5a0", "shop": "KoltCraftStudio", "listing_id": "1841132315", "source_url": "https://www.etsy.com/listing/1841132315/camphor-wood-clothes-hanger-with", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1841132315/camphor-wood-clothes-hanger-with", "title": "Camphor Wood Clothes Hanger with Adjustable Trouser Clips", "body": "Camphor Wood Clothes Hanger with Adjustable Trouser Clips Style: natural, classic. Materials: camphor_wood, metal. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Camphor Wood Hanger with Adjustable Trouser Clips", "new_body": "Organize trousers and skirts with a wooden hanger featuring adjustable metal clips and a curved shoulder design. From KoltCraftStudio. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/43671795/r/il/3c1ead/6517340566/il_1588xN.6517340566_7wcm.jpg", "checked_at": "2026-10-13T04:58:52.922Z"}, {"queue_id": "2c16eb9c-f807-460e-a998-0c711674b37b", "shop": "KoltCraftStudio", "listing_id": "1826865120", "source_url": "https://www.etsy.com/listing/1826865120/black-walnut-wood-coat-hanger-with-brass", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1826865120/black-walnut-wood-coat-hanger-with-brass", "title": "Black Walnut Wood Coat Hanger With Brass Hook", "body": "Black Walnut Wood Coat Hanger With Brass Hook Style: luxury, classic. Materials: walnut_wood, brass. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Black Walnut Coat Hanger with Brass Hook", "new_body": "Bring warm wood grain to your wardrobe with a curved black walnut hanger and brass hook. From KoltCraftStudio. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/43671795/r/il/c79012/6517347026/il_1588xN.6517347026_6gfp.jpg", "checked_at": "2026-10-13T04:59:32.795Z"}, {"queue_id": "2e7498ef-7c52-4f85-aa6a-528019c71fde", "shop": "HibiChStudio", "listing_id": "4374349912", "source_url": "https://www.etsy.com/listing/4374349912/canvas-wall-hanging-organizer-multi", "category": "Wall & Door Organizers", "image_url": null, "destination_url": "https://www.etsy.com/listing/4374349912/canvas-wall-hanging-organizer-multi", "title": "Canvas Wall Hanging Organizer, Multi Pocket Storage Bag, Over Door Bedside Organizer", "body": "Canvas Wall Hanging Organizer, Multi Pocket Storage Bag, Over Door Bedside Organizer Style: minimal, scandinavian. Materials: canvas. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Canvas Pocket Organizer for Walls and Doors", "new_body": "Keep stationery, glasses and small everyday items together with this canvas hanging organizer, finished with pockets and a wooden hanging rod. From HibiChStudio. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/59640782/r/il/5aab8b/7222312536/il_1588xN.7222312536_efei.jpg", "checked_at": "2026-10-13T04:59:41.495Z"}, {"queue_id": "68495c3b-f561-4927-a74f-ac59ed74b32b", "shop": "HibiChStudio", "listing_id": "4374362269", "source_url": "https://www.etsy.com/listing/4374362269/multi-pocket-hanging-bag-thick-wall", "category": "Wall & Door Organizers", "image_url": null, "destination_url": "https://www.etsy.com/listing/4374362269/multi-pocket-hanging-bag-thick-wall", "title": "Multi-Pocket Hanging Bag, Thick Wall Organizer for Bedside or Over-Door Storage", "body": "Multi-Pocket Hanging Bag, Thick Wall Organizer for Bedside or Over-Door Storage Style: minimal, natural. Materials: cotton, linen. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Neutral Fabric Wall Organizer with Multiple Pockets", "new_body": "Use vertical space for everyday essentials with a neutral cotton-linen hanging organizer and pockets in different sizes. From HibiChStudio. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/59640782/r/il/a56beb/7228694812/il_1588xN.7228694812_cfy0.jpg", "checked_at": "2026-10-13T04:59:47.918Z"}, {"queue_id": "734b7b99-482b-4a1c-a405-0ac776e51929", "shop": "MiawoodStudio", "listing_id": "1284508718", "source_url": "https://www.etsy.com/listing/1284508718/black-walnut-brass-hanger-solid-wood", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1284508718/black-walnut-brass-hanger-solid-wood", "title": "Black Walnut & Brass Hanger: Solid Wood Adult/Child Sizes", "body": "Black Walnut & Brass Hanger: Solid Wood Adult/Child Sizes Style: minimal, luxury. Materials: walnut_wood, brass. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Black Walnut and Brass Hangers for Closet Organization", "new_body": "A curved walnut body and brass hook create a coordinated wardrobe look. The listing offers adult and child hanger options. From MiawoodStudio. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/32100253/r/il/ab8181/6305748459/il_1588xN.6305748459_8k0x.jpg", "checked_at": "2026-10-13T04:59:55.685Z"}, {"queue_id": "66418577-fb71-4073-89e3-c2d55c163d31", "shop": "MiawoodStudio", "listing_id": "1781803827", "source_url": "https://www.etsy.com/listing/1781803827/vintage-walnut-round-hanger-360-degree", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1781803827/vintage-walnut-round-hanger-360-degree", "title": "Vintage Walnut Round Hanger - 360-Degree Swivel Metal Hook", "body": "Vintage Walnut Round Hanger - 360-Degree Swivel Metal Hook Style: vintage, functional. Materials: walnut_wood, metal. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Round Walnut Hanger for Scarves and Accessories", "new_body": "Organize scarves and ties with a round walnut hanger and swivel metal hook. Natural grain makes each wooden piece different. From MiawoodStudio. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/32100253/r/il/46c2aa/6212746840/il_1588xN.6212746840_8erm.jpg", "checked_at": "2026-10-13T05:00:11.442Z"}, {"queue_id": "f1f263ef-0d2d-497d-b242-d42e147cc360", "shop": "WoodHomeLiang", "listing_id": "1769992796", "source_url": "https://www.etsy.com/listing/1769992796/8-hooks-closet-organizer-rack-for", "category": "Closet Organization", "image_url": null, "destination_url": "https://www.etsy.com/listing/1769992796/8-hooks-closet-organizer-rack-for", "title": "8-Hooks Closet Organizer Rack for Ties, Natural Camphor Wood Tie Rack Hanger", "body": "8-Hooks Closet Organizer Rack for Ties, Natural Camphor Wood Tie Rack Hanger Style: natural, functional. Materials: camphor_wood, metal. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Wooden Multi-Hook Tie Organizer for the Closet", "new_body": "Keep ties and accessories visible with a wooden organizer fitted with multiple gold-tone hooks. From WoodHomeLiang. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/38928671/r/il/002805/6224081026/il_1588xN.6224081026_8e4v.jpg", "checked_at": "2026-10-13T05:00:19.811Z"}, {"queue_id": "6ab2b674-1d74-404a-a3c1-d0641cbea230", "shop": "WoodHomeLiang", "listing_id": "1752546922", "source_url": "https://www.etsy.com/listing/1752546922/retro-wooden-pants-hanger-with-metal", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1752546922/retro-wooden-pants-hanger-with-metal", "title": "Retro Wooden Pants Hanger With Metal Clips: Camphor Wood", "body": "Retro Wooden Pants Hanger With Metal Clips: Camphor Wood Style: retro, classic. Materials: camphor_wood, metal. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "863494997243989843", "new_title": "Wooden Clip Hangers for Trousers and Skirts", "new_body": "A straight wooden body and metal clips offer a simple way to arrange trousers and skirts in your wardrobe. From WoodHomeLiang. View the original Etsy listing for current options and details.", "new_image_url": "https://i.etsystatic.com/38928671/r/il/5b92fd/6144801526/il_1588xN.6144801526_bdv8.jpg", "checked_at": "2026-10-13T05:00:29.116Z"}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status in ('draft','ready') and cv.status in ('draft','ready') and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id and h.platform='pinterest')
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 8 then raise exception 'Expected 8 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;

update products p set primary_image_url=x.new_image_url,original_image_urls=jsonb_build_array(x.new_image_url),source_payload=coalesce(p.source_payload,'{}'::jsonb)||jsonb_build_object('material_verification',jsonb_build_object('source_url',x.source_url,'verified_at',x.checked_at,'image_verified',true,'batch','p2-20261013-2')) from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set image_url=x.new_image_url,title=x.new_title,body='A practical idea for your home: '||x.new_body||' '||x.source_url
from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.shop_id=q.shop_id and cv.platform='facebook' and cv.status='draft'
and not exists(select 1 from publish_history h where h.content_variant_id=cv.id)
and not exists(select 1 from publish_queue fq where fq.content_variant_id=cv.id and fq.status<>'draft');

insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;
commit;
